'use strict';
const api=location.pathname.startsWith('/online/')?'./api/index.php':'../api/index.php';
const $=id=>document.getElementById(id);
const BOOKING_STORE='kqonline_bookings_v1';
const DEVICE_STORE='kqonline_device_v1';
let installPrompt=null,bookingRequestKey='';
let onlineFeatures={online_booking:true,queue_status:true,qr_scanning:true};
const onlineFeaturesReady=fetch(`${api}?action=public-features`,{cache:'no-store'}).then(r=>r.json()).then(body=>{if(body.ok)onlineFeatures={...onlineFeatures,...body.data}}).catch(()=>{});
const isIos=/iphone|ipad|ipod/i.test(navigator.userAgent);
const isStandalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function digits(value){return String(value||'').replace(/\D/g,'')}
function validThaiCitizenId(value){const cid=digits(value);if(!/^\d{13}$/.test(cid)||/^(\d)\1{12}$/.test(cid))return false;let sum=0;for(let i=0;i<12;i++)sum+=Number(cid[i])*(13-i);return (11-sum%11)%10===Number(cid[12])}
function savedBookings(){try{return JSON.parse(localStorage.getItem(BOOKING_STORE)||'[]').filter(item=>item?.public_id)}catch{return []}}
async function reconcileSavedBookings(){const items=savedBookings();if(!items.length)return items;const checks=await Promise.all(items.map(async item=>{try{const response=await fetch(`${api}?action=queue-status&token=${encodeURIComponent(item.public_id)}`,{cache:'no-store'});return response.status===404?null:item}catch{return item}}));const valid=checks.filter(Boolean);if(valid.length!==items.length)localStorage.setItem(BOOKING_STORE,JSON.stringify(valid));return valid}
function deviceId(){let value=localStorage.getItem(DEVICE_STORE)||'';if(!/^[A-Za-z0-9_-]{16,128}$/.test(value)){value=crypto.randomUUID?.()||`${Date.now()}_${Math.random().toString(36).slice(2)}_${Math.random().toString(36).slice(2)}`;localStorage.setItem(DEVICE_STORE,value)}return value}
function rememberBooking(booking){const items=savedBookings().filter(item=>item.public_id!==booking.public_id);items.unshift({public_id:booking.public_id,reference_no:booking.reference_no,slot_date:$('bookingDate').value,created_at:new Date().toISOString()});localStorage.setItem(BOOKING_STORE,JSON.stringify(items.slice(0,20)))}
function updateNetworkStatus(){const offline=!navigator.onLine;$('networkStatus').classList.toggle('hidden',!offline);document.querySelector('#bookingForm button[type="submit"]').disabled=offline||!onlineFeatures.online_booking}
window.addEventListener('online',()=>{updateNetworkStatus();loadSlots().catch(showError)});window.addEventListener('offline',updateNetworkStatus);updateNetworkStatus();
function showInstallGuide(){$('installGuideTitle').textContent='ติดตั้ง K-QOnline';let html;if(isIos)html='<p>เปิดหน้านี้ด้วย Safari แล้วกดปุ่ม <strong>แชร์</strong> จากนั้นเลือก <strong>เพิ่มไปยังหน้าจอโฮม</strong></p>';else if(!window.isSecureContext)html='<p>การติดตั้งแอปต้องเปิดผ่าน HTTPS กรุณาใช้ลิงก์ HTTPS ของ K-QOnline</p>';else html='<p>เลือก <strong>ติดตั้งแอป</strong> หรือ <strong>เพิ่มลงในหน้าจอหลัก</strong> จากเมนูของ Chrome หากเมนูยังไม่แสดง ให้รีเฟรชหน้าแล้วลองอีกครั้ง</p>';$('installGuideContent').innerHTML=html;$('installGuide').classList.remove('hidden')}
function closeInstallGuide(){$('installGuide').classList.add('hidden')}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('installApp').textContent='ติดตั้งแอป'});
$('installApp').onclick=async()=>{if(isStandalone){$('installGuideContent').innerHTML='<p>K-QOnline ถูกเปิดในโหมดแอปแล้ว</p>';$('installGuide').classList.remove('hidden');return}if(!installPrompt){showInstallGuide();return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null};
$('closeInstallGuide').onclick=closeInstallGuide;$('dismissInstallGuide').onclick=closeInstallGuide;$('installGuide').onclick=event=>{if(event.target===$('installGuide'))closeInstallGuide()};
window.addEventListener('appinstalled',()=>{$('installApp').classList.add('hidden')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js?v=17').catch(()=>{}));
async function loadSlots(){await onlineFeaturesReady;if(!onlineFeatures.online_booking){$('onlineSlot').innerHTML='<option value="">ปิดรับจองออนไลน์ชั่วคราว</option>';document.querySelector('#bookingForm button[type="submit"]').disabled=true;throw new Error('ระบบจองคิวออนไลน์ถูกปิดใช้งาน กรุณาติดต่อเจ้าหน้าที่')}const response=await fetch(`${api}?action=public-slots&date=${encodeURIComponent($('bookingDate').value)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'โหลด Slot ไม่สำเร็จ');$('onlineSlot').innerHTML=body.data.map(x=>`<option value="${x.id}">${String(x.start_time).slice(0,5)}–${String(x.end_time).slice(0,5)} น. · ${x.branch_name} · ${x.department_name}${x.service_name?` · ${x.service_name}`:''}</option>`).join('')||'<option value="">ไม่มี Slot ที่เปิดรับ</option>';document.querySelector('#bookingForm button[type="submit"]').disabled=!body.data.length||!navigator.onLine}
function showError(error){$('bookingError').textContent=error.message;$('bookingError').classList.remove('hidden')}
try{const today=KQThaiDate.todayISO();$('bookingDate').innerHTML=KQThaiDate.options(today,0,90);$('bookingDate').value=today}catch(error){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date());$('bookingDate').innerHTML=`<option value="${today}">${KQThaiDate.date(today)}</option>`;showError(new Error('ปฏิทินแสดงได้บางส่วน กรุณารีเฟรชหน้าอีกครั้ง'))}
$('bookingDate').onchange=()=>{bookingRequestKey='';loadSlots().catch(showError)};loadSlots().catch(showError);
reconcileSavedBookings().catch(()=>{});
$('bookingForm').addEventListener('input',()=>{bookingRequestKey=''});
$('bookingForm').onsubmit=async event=>{event.preventDefault();$('bookingError').classList.add('hidden');if(!navigator.onLine){showError(new Error('กรุณาเชื่อมต่ออินเทอร์เน็ตก่อนยืนยันการจอง'));return}const existing=savedBookings().find(item=>item.slot_date===$('bookingDate').value);if(existing){showError(new Error(`มือถือเครื่องนี้จองคิวสำหรับวันที่เลือกแล้ว (${existing.reference_no}) กรุณาเปิดเมนูคิวของฉัน`));return}const citizenId=digits($('onlineCitizen').value);if(!validThaiCitizenId(citizenId)){showError(new Error('เลขบัตรประชาชนไม่ถูกต้อง กรุณาตรวจสอบ 13 หลัก'));$('onlineCitizen').focus();return}const phone=digits($('onlinePhone').value);if(phone.length<9||phone.length>10){showError(new Error('หมายเลขโทรศัพท์ไม่ถูกต้อง'));$('onlinePhone').focus();return}if(!$('onlineSlot').value){showError(new Error('ไม่มี Slot ที่เปิดรับในวันที่เลือก'));return}const submit=event.submitter||event.currentTarget.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent='กำลังยืนยันการจอง…';if(!bookingRequestKey)bookingRequestKey=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;try{const response=await fetch(`${api}?action=create-booking`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot_id:+$('onlineSlot').value,customer_name:$('onlineName').value.trim(),customer_phone:phone,citizen_id:citizenId,device_id:deviceId(),source:'ONLINE',idempotency_key:bookingRequestKey})});const body=await response.json();if(!response.ok)throw new Error(body.error||'จองคิวไม่สำเร็จ');rememberBooking(body.booking);render(body.booking);bookingRequestKey=''}catch(error){showError(error)}finally{submit.disabled=false;submit.textContent='ยืนยันการจอง'}};
function render(booking){const url=new URL('status.html',location.href);url.searchParams.set('t',booking.public_id);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('bookingQr').src=qr.createDataURL(7,10);$('bookingStatusLink').href=url.href;$('bookingReference').textContent=`เลขอ้างอิง ${booking.reference_no}`;$('bookingToken').textContent=booking.public_id;$('bookingPanel').classList.add('hidden');$('bookingResult').classList.remove('hidden')}
$('bookAgain').onclick=()=>{$('bookingResult').classList.add('hidden');$('bookingPanel').classList.remove('hidden');$('bookingForm').reset();const today=KQThaiDate.todayISO();$('bookingDate').value=today;bookingRequestKey='';loadSlots().catch(showError)};
$('saveBooking').onclick=()=>{const link=document.createElement('a');link.href=$('bookingQr').src;link.download='K-QOnline-QR.png';link.click()};
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.tab;if(action==='install'){$('installApp').click();return}if(action==='help'){$('installGuideTitle').textContent='วิธีใช้ K-QOnline';$('installGuideContent').innerHTML='<ol class="help-steps"><li>เลือกวันที่และ Slot ที่สะดวก</li><li>กรอกชื่อ CID และเบอร์โทรศัพท์</li><li>กดยืนยันแล้วบันทึก QR</li><li>นำ QR ไปเช็กอินที่ Kiosk เมื่อมาถึง</li><li>ติดตามสถานะจากเมนูคิวของฉัน</li></ol>';$('installGuide').classList.remove('hidden');return}$('bookingResult').classList.add('hidden');$('bookingPanel').classList.remove('hidden');$('bookingPanel').scrollIntoView({behavior:'smooth',block:'start'});if(action==='booking')setTimeout(()=>$('bookingDate').focus(),350)}));
